:7},{"id":315,"sku":"CL-0315","barcode":"","image":"","name":"whiskas pouch 80 gr","baseName":"whiskas pouch 80 gr","sell":7000.0,"cost":5393.0,"tiers":[{"minQty":1,"sell":7000.0,"cost":5393.0},{"minQty":3,"sell":6667.0,"cost":5393.0},{"minQty":12,"sell":6500.0,"cost":5393.0},{"minQty":24,"sell":6250.0,"cost":5393.0},{"minQty":28,"sell":6143.0,"cost":5393.0}],"stock":714,"trackStock":true,"active":true,"needsPrice":false,"finalStock":671}]$oct$::jsonb) as item(
  id bigint, sku text, barcode text, image text, name text, "baseName" text,
  sell numeric, cost numeric, tiers jsonb, stock integer, "finalStock" integer,
  "trackStock" boolean, active boolean, "needsPrice" boolean
);

update public.products product
set name = incoming.name,
    base_name = incoming."baseName",
    sell_price = round(incoming.sell),
    cost_price = round(incoming.cost),
    stock = incoming.stock,
    track_stock = true,
    active = incoming.active,
    pricing_rule = jsonb_build_object('tiers', incoming.tiers),
    updated_at = now()
from incoming_oct_catalog incoming
where product.store_id = '24a3a058-991b-4b64-b1d2-912910842d34'::uuid
  and (product.local_id = incoming.id or lower(btrim(coalesce(product.base_name, product.name))) = lower(btrim(incoming.name)));

insert into public.products (store_id, local_id, sku, barcode, name, base_name, sell_price, cost_price, stock, track_stock, active, pricing_rule)
select '24a3a058-991b-4b64-b1d2-912910842d34'::uuid, incoming.id,
       case when exists (select 1 from public.products conflict where conflict.store_id = '24a3a058-991b-4b64-b1d2-912910842d34'::uuid and conflict.sku = incoming.sku) then 'CL-Q4-' || incoming.id::text else incoming.sku end,
       case when nullif(incoming.barcode, '') is null or exists (select 1 from public.products conflict where conflict.store_id = '24a3a058-991b-4b64-b1d2-912910842d34'::uuid and conflict.barcode = incoming.barcode) then null else incoming.barcode end,
       incoming.name, incoming."baseName", round(incoming.sell), round(incoming.cost), incoming.stock, true, incoming.active, jsonb_build_object('tiers', incoming.tiers)
from incoming_oct_catalog incoming
where not exists (
  select 1 from public.products product
  where product.store_id = '24a3a058-991b-4b64-b1d2-912910842d34'::uuid
    and (product.local_id = incoming.id or lower(btrim(coalesce(product.base_name, product.name))) = lower(btrim(incoming.name)))
);

update public.products product set active = false, updated_at = now()
where product.store_id = '24a3a058-991b-4b64-b1d2-912910842d34'::uuid
  and not exists (select 1 from incoming_oct_catalog incoming where lower(btrim(incoming.name)) = lower(btrim(coalesce(product.base_name, product.name))));

create temporary table old_october_sales on commit drop as
select id from public.sales where store_id = '24a3a058-991b-4b64-b1d2-912910842d34'::uuid and business_date = date '2026-10-01';

delete from public.inventory_movement_change_requests request
where request.store_id = '24a3a058-991b-4b64-b1d2-912910842d34'::uuid
  and exists (select 1 from public.inventory_movements movement join old_october_sales old_sale on movement.reference_id = old_sale.id::text where movement.id = request.movement_id);
delete from public.inventory_movements movement
where movement.store_id = '24a3a058-991b-4b64-b1d2-912910842d34'::uuid and exists (select 1 from old_october_sales old_sale where movement.reference_id = old_sale.id::text);
delete from public.audit_logs log
where log.store_id = '24a3a058-991b-4b64-b1d2-912910842d34'::uuid and exists (select 1 from old_october_sales old_sale where log.entity_id = old_sale.id::text);
delete from public.sales sale
where sale.store_id = '24a3a058-991b-4b64-b1d2-912910842d34'::uuid and sale.business_date = date '2026-10-01';

delete from public.pos_receipt_sequences where store_id = '24a3a058-991b-4b64-b1d2-912910842d34'::uuid and month_key = '202610';

