delete from public.sale_deletions deletion
where deletion.store_id = '24a3a058-991b-4b64-b1d2-912910842d34'::uuid and exists (select 1 from incoming_october_sales incoming where incoming.id = deletion.sale_id);

insert into public.sales (
  id, store_id, receipt_number, cashier_id, cashier_name, items, total, cost_total,
  payment_method, payment_breakdown, cash_received, change_due, status, correction_reason,
  business_date, created_at, updated_at, payment_edit_history
)
select sale.id, '24a3a058-991b-4b64-b1d2-912910842d34'::uuid, sale.receipt, null, sale.cashier, sale.items, sale.total, sale.cost,
       sale."paymentMethod", sale."paymentBreakdown", sale.cash, sale.change, sale.status, sale.reason,
       date '2026-10-01', sale."createdAt", now(), '[]'::jsonb
from incoming_october_sales sale
order by sale.trx;

update public.products product
set stock = incoming."finalStock", track_stock = true, updated_at = now()
from incoming_oct_catalog incoming
where product.store_id = '24a3a058-991b-4b64-b1d2-912910842d34'::uuid
  and (product.local_id = incoming.id or lower(btrim(coalesce(product.base_name, product.name))) = lower(btrim(incoming.name)));

insert into public.audit_logs (id, store_id, actor_id, actor_name, actor_role, action, entity_id, detail, created_at)
values (
  'excel-import-2026-10-01', '24a3a058-991b-4b64-b1d2-912910842d34'::uuid, null, 'Owner CL Petshop', 'owner',
  'IMPORT_EXCEL_SALES', '2026-10-01',
  'SO 30 September diterapkan lalu 87 transaksi Excel 1 Oktober diimpor. Omzet Rp5.070.000.', now()
)
on conflict (id) do update set detail = excluded.detail, created_at = excluded.created_at;

do $validation$
declare
  preserved_before record;
  preserved_after record;
  oct_count bigint;
  oct_total bigint;
  oct_cost bigint;
  wrong_stock bigint;
begin
  select * into preserved_before from preserved_sales_before;
  select count(*)::bigint as sale_count, coalesce(sum(total), 0)::bigint as omzet, coalesce(sum(cost_total), 0)::bigint as hpp
  into preserved_after
  from public.sales where store_id = '24a3a058-991b-4b64-b1d2-912910842d34'::uuid and business_date < date '2026-10-01';
  if row(preserved_before.sale_count, preserved_before.omzet, preserved_before.hpp) is distinct from row(preserved_after.sale_count, preserved_after.omzet, preserved_after.hpp) then
    raise exception 'Historical sales before October changed';
  end if;

  select count(*), coalesce(sum(total), 0), coalesce(sum(cost_total), 0)
  into oct_count, oct_total, oct_cost
  from public.sales where store_id = '24a3a058-991b-4b64-b1d2-912910842d34'::uuid and business_date = date '2026-10-01';
  if oct_count <> 87 or oct_total <> 5070000 or oct_cost <> 4393031 then
    raise exception 'October import validation failed: count %, omzet %, hpp %', oct_count, oct_total, oct_cost;
  end if;

  select count(*) into wrong_stock
  from public.products product
  join incoming_oct_catalog incoming on lower(btrim(coalesce(product.base_name, product.name))) = lower(btrim(incoming.name))
  where product.store_id = '24a3a058-991b-4b64-b1d2-912910842d34'::uuid and product.stock <> incoming."finalStock";
  if wrong_stock <> 0 then raise exception 'Final stock validation failed: %', wrong_stock; end if;

  if (select count(*) from public.sales where store_id = '24a3a058-991b-4b64-b1d2-912910842d34'::uuid and business_date = date '2026-10-01' and payment_method = 'cash') <> 63
     or (select coalesce(sum(total),0) from public.sales where store_id = '24a3a058-991b-4b64-b1d2-912910842d34'::uuid and business_date = date '2026-10-01' and payment_method = 'cash') <> 2809000
     or (select count(*) from public.sales where store_id = '24a3a058-991b-4b64-b1d2-912910842d34'::uuid and business_date = date '2026-10-01' and payment_method = 'qris') <> 15
     or (select coalesce(sum(total),0) from public.sales where store_id = '24a3a058-991b-4b64-b1d2-912910842d34'::uuid and business_date = date '2026-10-01' and payment_method = 'qris') <> 864000
     or (select count(*) from public.sales where store_id = '24a3a058-991b-4b64-b1d2-912910842d34'::uuid and business_date = date '2026-10-01' and payment_method = 'transfer') <> 6
     or (select coalesce(sum(total),0) from public.sales where store_id = '24a3a058-991b-4b64-b1d2-912910842d34'::uuid and business_date = date '2026-10-01' and payment_method = 'transfer') <> 1270000
     or (select count(*) from public.sales where store_id = '24a3a058-991b-4b64-b1d2-912910842d34'::uuid and business_date = date '2026-10-01' and payment_method = 'debit') <> 3
     or (select coalesce(sum(total),0) from public.sales where store_id = '24a3a058-991b-4b64-b1d2-912910842d34'::uuid and business_date = date '2026-10-01' and payment_method = 'debit') <> 127000 then
    raise exception 'Payment totals validation failed';
  end if;
end
$validation$;

commit;
